"use client"

import { useState } from "react"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Pencil } from "lucide-react"

interface Record {
  firstName: string
  lastName: string
  phone: string
  email: string
  address: string
  state: string
  district: string
  city: string
  zip: string
}

export default function Home() {
  const [form, setForm] = useState<Record>({
    firstName: "",
    lastName: "",
    phone: "",
    email: "",
    address: "",
    state: "",
    district: "",
    city: "",
    zip: "",
  })

  const [records, setRecords] = useState<Record[]>([
    { firstName: "John", lastName: "Doe", phone: "(208) 555-0112", email: "jonhd@gmail.com", address: "738 N JORDAN ST ALLENTOWN PA 18102-1841", state: "PA", district: "PA", city: "chicago", zip: "574855" },
    { firstName: "Jane", lastName: "Smith", phone: "(208) 555-0112", email: "janes@gmail.com", address: "738 N JORDAN ST ALLENTOWN PA 18102-1841", state: "PA", district: "PA", city: "san fransico", zip: "847595" },
    { firstName: "Tracy", lastName: "Randall", phone: "(208) 555-0112", email: "traceyr@gmail.com", address: "738 N JORDAN ST ALLENTOWN PA 18102-1841", state: "PA", district: "PA", city: "michigan", zip: "584745" },
    { firstName: "Micheale", lastName: "Joey", phone: "(208) 555-0112", email: "MichealJ@gmail.com", address: "738 N JORDAN ST ALLENTOWN PA 18102-1841", state: "PA", district: "PA", city: "minniapolis", zip: "595059" },
    { firstName: "Mark", lastName: "Looney", phone: "(208) 555-0112", email: "MarkL@gmail.com", address: "738 N JORDAN ST ALLENTOWN PA 18102-1841", state: "PA", district: "PA", city: "indianapplis", zip: "494850" },
    { firstName: "Roger", lastName: "Joyce", phone: "(208) 555-0112", email: "rogerJ@gmail.com", address: "738 N JORDAN ST ALLENTOWN PA 18102-1841", state: "PA", district: "PA", city: "texas", zip: "849485" },
  ])

  const handleChange = (key: keyof Record, value: string) => {
    setForm({ ...form, [key]: value })
  }

  const handleSave = () => {
    setRecords([...records, form])
    setForm({
      firstName: "",
      lastName: "",
      phone: "",
      email: "",
      address: "",
      state: "",
      district: "",
      city: "",
      zip: "",
    })
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-6">
      {/* Left Form Section */}
      <Card>
        <CardHeader>
          <CardTitle>Add / Edit the single record Here</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <Label>First Name</Label>
            <Input value={form.firstName} onChange={(e) => handleChange("firstName", e.target.value)} />
          </div>
          <div>
            <Label>Last Name</Label>
            <Input value={form.lastName} onChange={(e) => handleChange("lastName", e.target.value)} />
          </div>
          <div>
            <Label>Phone (Primary)</Label>
            <Input value={form.phone} onChange={(e) => handleChange("phone", e.target.value)} />
          </div>
          <div>
            <Label>Email</Label>
            <Input value={form.email} onChange={(e) => handleChange("email", e.target.value)} />
          </div>
          <div>
            <Label>Address</Label>
            <Input value={form.address} onChange={(e) => handleChange("address", e.target.value)} />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label>State</Label>
              <Select onValueChange={(val) => handleChange("state", val)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select State" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="CA">CA</SelectItem>
                  <SelectItem value="PA">PA</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>District</Label>
              <Select onValueChange={(val) => handleChange("district", val)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select District" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="CA">CA</SelectItem>
                  <SelectItem value="PA">PA</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label>City</Label>
              <Input value={form.city} onChange={(e) => handleChange("city", e.target.value)} />
            </div>
            <div>
              <Label>Zip Code</Label>
              <Input value={form.zip} onChange={(e) => handleChange("zip", e.target.value)} />
            </div>
          </div>

          <div className="flex justify-end gap-4">
            <Button variant="outline">Cancel</Button>
            <Button onClick={handleSave}>Save</Button>
          </div>
        </CardContent>
      </Card>

      {/* Right Table Section */}
      <Card>
        <CardHeader>
          <CardTitle>Show the List of records</CardTitle>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Action</TableHead>
                <TableHead>First Name</TableHead>
                <TableHead>Last Name</TableHead>
                <TableHead>Phone</TableHead>
                <TableHead>Email</TableHead>
                <TableHead>Address</TableHead>
                <TableHead>City</TableHead>
                <TableHead>Zip</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {records.map((rec, i) => (
                <TableRow key={i}>
                  <TableCell><Pencil className="w-4 h-4 cursor-pointer" /></TableCell>
                  <TableCell>{rec.firstName}</TableCell>
                  <TableCell>{rec.lastName}</TableCell>
                  <TableCell>{rec.phone}</TableCell>
                  <TableCell>{rec.email}</TableCell>
                  <TableCell>{rec.address}</TableCell>
                  <TableCell>{rec.city}</TableCell>
                  <TableCell>{rec.zip}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>

          {/* Pagination + Entries per page */}
          <div className="flex justify-between items-center mt-4">
            <div className="flex items-center gap-2">
              <span>Show</span>
              <Select>
                <SelectTrigger className="w-16">
                  <SelectValue placeholder="10" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="10">10</SelectItem>
                  <SelectItem value="20">20</SelectItem>
                  <SelectItem value="50">50</SelectItem>
                </SelectContent>
              </Select>
              <span>entries per page</span>
            </div>
            <div className="flex items-center gap-2">
              <span>1-10 of {records.length}</span>
              <Button variant="outline" size="sm">{"<"}</Button>
              <Button variant="outline" size="sm">{">"}</Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}
